window.BattleVictoryCard={mount(panel){const card=document.createElement('section');card.className='victory-card';card.hidden=true;panel.querySelector('.result-actions').before(card);
 function figure(image,label){const node=document.createElement('figure'),caption=document.createElement('figcaption');if(Craft.validArtwork(image)){const img=document.createElement('img');img.src=image;img.alt=label;node.append(img);}caption.textContent=label;node.append(caption);return node;}
 return{update(state,run){card.hidden=!(state.ended&&state.enemyHp===0&&state.stage===BattlePreview.encounters.length-1);if(card.hidden)return;card.replaceChildren();const weapon=BattlePreview.weapon,tier=Craft.Rarity.get(weapon.rarity),title=document.createElement('strong'),art=document.createElement('div'),record=document.createElement('p'),finish=document.createElement('p');title.textContent=tier.label+' · '+weapon.name;title.className='victory-weapon-name';title.style.setProperty('--rarity-color',GamePalette.tokens[tier.color]);art.className='victory-art';const data=run||{victories:[]};if(data.originalImage&&data.originalImage!==weapon.artwork)art.append(figure(data.originalImage,'처음 그린 '+data.originalName));art.append(figure(weapon.artwork,weapon.evolution?weapon.evolution.stage+'차 진화한 모습':'네가 그린 무기'));const defeated=data.victories.map(v=>BattlePreview.getEncounter(v.stage).name);record.textContent='쓰러뜨린 상대 · '+defeated.join(' → ');const last=data.victories.find(v=>v.stage===state.stage);finish.textContent='결정타 · '+(last?.finisher||'마지막 공격');finish.className='victory-finisher';card.append(title,art,record,finish);}};
}};
